def compute(vars):
    margin_2019 = vars["v1"]
    margin_2018 = vars["v2"]
    larger_year = 2019 if margin_2019 > margin_2018 else 2018 if margin_2018 > margin_2019 else None

    return {
        "value": larger_year,
        "trace": {
            "gross_margin_2019": margin_2019,
            "gross_margin_2018": margin_2018,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year"
            }
        }
    }
